Definition wf (s : sto) : Prop :=
  words_ok (s_words s) /\ (size s <= capacity s)%nat /\ (s_alloc s = false -> s_cap s = inlined_capacity).

Definition reduced_ws (ws : words) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$ws;R'0!2+1!3+2'0#1!1,3+4!1'5!3+2+4!3'6+4#1,7,7").
Definition reduced (s : sto) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$s;R+8!1'9!1':#1").

