Definition ev_ok (B : Z) (e : event) : Prop :=
  match e with EAlloc _ b _ => 0 <= b <= B | _ => True end.
Fixpoint nallocs (l : list event) : nat :=
  match l with [] => O | EAlloc _ _ _ :: t => S (nallocs t) | _ :: t => nallocs t end.
