Lemma resize_mspec N s n : okN N s -> (n <= N)%nat ->
  mspec (resize s n)
    (fun s' => okN N s' /\ s_words s' = firstn n (s_words s) ++ zeros (n - size s) /\ size s' = n /\ s_neg s' = s_neg s
