Lemma assign_mspec N dst src : okN N dst -> okN N src -> (size src <= N)%nat ->
  mspec (assign dst src) (fun s' => okN N s' /\ s_words s' = s_words src /\ size s' = size src
                                   /\ s_neg s' = (if (0 <? size src)%nat then s_neg src else s_neg dst)
