Definition cmp3 (a b : Z) : Z := match a ?= b with Lt => -1 | Eq => 0 | Gt => 1 end.

Lemma compare_loop_spec xs ys : words_ok xs -> words_ok ys -> forall n, (n <= length xs)%nat -> (n <= length ys)%nat ->
