Lemma cmp3_lt a b : a < b -> cmp3 a b = -1.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 2 "S20!1,_>,^<!2'`;#3#2$a;R+4$b;R+4$~R!2'_9#2#1vd!6'^C+`:,gE$c;R+`:!3+2+4-`:RN$x;R+`:+4#13,70!1,G,^<0!2,K+401!4'gC%~R!3+2+`:1,gE!2'_9#4#3%~R!2'_9#3#2!3+2+`:!2'`;#4#3,gE!2'gF#3#2#1!3+2+4!2'g@#3#20").
